1. # hosts/rpi/configuration.nix — Raspberry Pi 4 k3s worker
2. #
3. # Host-specific settings only. Shared config comes from profiles where the
4. # Raspberry Pi boot path does not need special handling.
5. { config, lib, pkgs, ... }:
6. 
7. let
8.   hostSecretsFile = ../../secrets/rpi/secrets.yaml;
9.   hasHostSecretsFile = builtins.pathExists hostSecretsFile;
10.   hasTailscaleSecretsFile = builtins.pathExists ../../secrets/tailscale/secrets.yaml;
11. in
12. {
13.   imports = [
14.     ../../profiles/base.nix
15.     ../../profiles/tailscale.nix
16.     ../../profiles/k3s-agent.nix
17.     ../../profiles/smartd.nix
18.     ./disko-config.nix
19.     ./sops.nix
20.   ];
21. 
22.   nixpkgs.hostPlatform = lib.mkDefault "aarch64-linux";
23. 
24.   # Pi-only binary cache (keep out of shared profiles/base.nix)
25.   nix.settings = {
26.     substituters = lib.mkAfter [ "https://nixos-raspberrypi.cachix.org" ];
27.     trusted-public-keys = lib.mkAfter [
28.       "nixos-raspberrypi.cachix.org-1:REDACTED/j2oiYLNOQ5sPI="
29.     ];
30.   };
31. 
32.   boot.loader.raspberry-pi = {
33.     enable = true;
34.     bootloader = "kernel";
35.   };
36. 
37.   boot.kernelParams = [
38.     "console=tty0"
39.     "console=ttyAMA0,115200n8"
40.     "cgroup_enable=cpuset"
41.     "cgroup_enable=memory"
42.     "cgroup_memory=1"
43.     "rootwait"
44.   ];
45. 
46.   boot.initrd.availableKernelModules = [
47.     "mmc_block"
48.     "sd_mod"
49.     "uas"
50.     "usb_storage"
51.     "usbhid"
52.     "xhci_pci"
53.   ];
54. 
55.   hardware.enableRedistributableFirmware = true;
56. 
57.   networking.hostName = "rpi";
58.   networking.useDHCP = lib.mkDefault true;
59.   networking.networkmanager.enable = true;
60.   networking.networkmanager.ensureProfiles = lib.mkMerge [
61.     {
62.       profiles.rpi-wired = {
63.         connection = {
64.           id = "rpi-wired";
65.           type = "ethernet";
66.           autoconnect = true;
67.           autoconnect-priority = 100;
68.         };
69. 
70.         ipv4.method = "auto";
71.         ipv6.method = "auto";
72.       };
73.     }
74.     (lib.mkIf hasHostSecretsFile {
75.       environmentFiles = [
76.         config.sops.templates."rpi-network.env".path
77.       ];
78. 
79.       profiles.rpi-wifi = {
80.         connection = {
81.           id = "rpi-wifi";
82.           type = "wifi";
83.           interface-name = "wlan0";
84.           autoconnect = true;
85.         };
86. 
87.         wifi = {
88.           mode = "infrastructure";
89.           ssid = "$WIFI_SSID";
90.         };
91. 
92.         wifi-security = {
93.           key-mgmt = "wpa-psk";
94.           psk = "$WIFI_PSK";
95.         };
96. 
97.         ipv4.method = "auto";
98.         ipv6.method = "auto";
99.       };
100.     })
101.   ];
102. 
103.   networking.firewall = {
104.     allowedTCPPorts = [ 22 ];
105.     trustedInterfaces = [
106.       "tailscale0"
107.     ];
108.   };
109. 
110.   time.timeZone = "Asia/Kolkata";
111. 
112.   services.openssh.enable = true;
113.   services.openssh.openFirewall = true;
114. 
115.   services.openssh.settings = {
116.     PasswordAuthentication = false;
117.     KbdInteractiveAuthentication = false;
118.     PermitRootLogin = "no";
119.   };
120. 
121.   services.journald.extraConfig = ''
122.     Storage=persistent
123.   '';
124. 
125.   # Tailscale — host identity + exit node + LAN subnet router.
126.   services.tailscale.useRoutingFeatures = "server";
127.   services.tailscale.extraUpFlags = lib.mkIf hasTailscaleSecretsFile [
128.     "--hostname=rpi"
129.     "--accept-dns=false"
130.   ];
131.   services.tailscale.extraSetFlags = [
132.     "--advertise-exit-node"
133.     "--advertise-routes=10.0.0.0/24"
134.   ];
135. 
136.   # k3s — worker in the s145-rooted cluster.
137.   services.k3s.nodeName = "rpi";
138.   services.k3s.nodeIP = "100.118.166.120";
139.   systemd.services.k3s.serviceConfig.ExecCondition =
140.     "${pkgs.runtimeShell} -c 'grep -qw memory /sys/fs/cgroup/cgroup.controllers'";
141. 
142.   zramSwap = {
143.     enable = true;
144.     algorithm = "zstd";
145.     memoryPercent = 50;
146.   };
147. 
148.   system.stateVersion = "26.05";
149. }
