1. # profiles/base.nix — applied to every OCI host
2. #
3. # Provides the absolute baseline: nix daemon settings, garbage collection,
4. # minimal system footprint, and the shared user account.
5. { ... }:
6. {
7.   # Nix settings
8.   nix.settings = {
9.     trusted-users = [
10.       "root"
11.       "duck"
12.     ];
13.     # Nix 2.34+ ignores flake nixConfig substituters unless this is set
14.     # (otherwise builds fall back to compiling from source).
15.     accept-flake-config = true;
16.     extra-experimental-features = [
17.       "nix-command"
18.       "flakes"
19.     ];
20.     substituters = [
21.       "https://cache.nixos.org"
22.       "https://nix-community.cachix.org"
23.     ];
24.     trusted-public-keys = [
25.       "cache.nixos.org-1:REDACTED"
26.       "nix-community.cachix.org-1:b9F6KGrNS7LDfJs+c9UF4/tEaS7KE0mTChZdG4h6IVk="
27.     ];
28.   };
29. 
30.   nix.gc = {
31.     automatic = true;
32.     dates = "weekly";
33.     options = "--delete-older-than 7d";
34.     randomizedDelaySec = "45min";
35.   };
36. 
37.   nix.optimise = {
38.     automatic = true;
39.     dates = [ "weekly" ];
40.     randomizedDelaySec = "45min";
41.   };
42. 
43.   # Minimal system — no docs, no default packages
44.   documentation.enable = false;
45.   programs.command-not-found.enable = false;
46.   environment.defaultPackages = [ ];
47.   environment.systemPackages = [ ];
48. 
49.   # Shared user account
50.   users.mutableUsers = false;
51. 
52.   users.users.root = {
53.     hashedPassword = "!";
54.     openssh.authorizedKeys.keys = [ ];
55.   };
56. 
57.   users.users.duck = {
58.     isNormalUser = true;
59. 
60.     extraGroups = [
61.       "wheel"
62.       "networkmanager"
63.     ];
64. 
65.     hashedPassword = "!";
66. 
67.     openssh.authorizedKeys.keys = [
68.       "ssh-ed25519 REDACTED jesbin@Duck.local"
69.       "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIEDGmT5meeiDIK9c/W8imy++S7hb9TLBcHcPsWcml4D2 duck@Ducks-MacBook-Air.local"
70.       "ssh-ed25519 REDACTED jesbin@Jesbins-MacBook-Pro.local"
71.     ];
72.   };
73. 
74.   security.sudo.wheelNeedsPassword = false;
75. }
