1. # profiles/smartd.nix — SMART disk health monitoring for bare-metal hosts
2. #
3. # Import only on physical machines (s145, hp348, rpi). Do not import on OCI
4. # VMs — cloud block devices usually lack useful SMART data.
5. {
6.   # Surface impending disk failure before data loss.
7.   services.smartd = {
8.     enable = true;
9.     autodetect = true;
10.     notifications.test = false;
11.   };
12. }
